using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var rows=new List<object>();foreach(var mode in new[]{ParticleSystemScalingMode.Hierarchy,ParticleSystemScalingMode.Local,ParticleSystemScalingMode.Shape})foreach(var local in new[]{false,true})foreach(var euler in new[]{Vector3.zero,new Vector3(-90,0,0),new Vector3(23,47,11)})foreach(var scale in new[]{Vector3.one,Vector3.one*1.3f,new Vector3(1,2,3)})foreach(var parentScale in new[]{1f,2f}){var parent=new GameObject("start-speed-parent"){hideFlags=HideFlags.HideAndDontSave};try{parent.transform.localScale=Vector3.one*parentScale;var go=new GameObject("start-speed-probe"){hideFlags=HideFlags.HideAndDontSave};go.transform.SetParent(parent.transform,false);go.transform.localRotation=Quaternion.Euler(euler);go.transform.localScale=scale;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.startSpeed=5;main.startLifetime=10;main.scalingMode=mode;main.simulationSpace=local?ParticleSystemSimulationSpace.Local:ParticleSystemSimulationSpace.World;var em=ps.emission;em.enabled=false;var sh=ps.shape;sh.enabled=false;ps.Play();ps.Pause();ps.Emit(1);var p=new ParticleSystem.Particle[1];for(int i=0;i<12;i++)ps.Simulate(1f/60,false,false,false);ps.GetParticles(p);var v=p[0].velocity;var pos=p[0].position;rows.Add(new{mode=(int)mode,local,euler=new[]{euler.x,euler.y,euler.z},scale=new[]{scale.x,scale.y,scale.z},parentScale,position=new[]{pos.x,pos.y,pos.z},velocity=new[]{v.x,v.y,v.z}});}finally{UnityEngine.Object.DestroyImmediate(parent);}}File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,rows}));return "Start speed cases="+rows.Count;}}

